begin;
create view public.budget_salary_projection with(security_invoker=true) as
with months as (select generate_series(date_trunc('month',current_date),date_trunc('year',current_date)+interval '11 months',interval '1 month')::date competence_month), active_terms as (select ct.tenant_id,ct.company_id,ct.employment_contract_id,m.competence_month,ct.base_salary,ea.cost_center_id,ea.allocation_percent from public.compensation_terms ct cross join months m join public.employment_contracts ec on ec.tenant_id=ct.tenant_id and ec.company_id=ct.company_id and ec.id=ct.employment_contract_id left join public.employee_allocations ea on ea.tenant_id=ct.tenant_id and ea.company_id=ct.company_id and ea.employment_contract_id=ct.employment_contract_id and ea.valid_from<=(m.competence_month+interval '1 month - 1 day')::date and (ea.valid_to is null or ea.valid_to>=m.competence_month) where ct.valid_from<=(m.competence_month+interval '1 month - 1 day')::date and (ct.valid_to is null or ct.valid_to>=m.competence_month) and ec.hired_on<=(m.competence_month+interval '1 month - 1 day')::date and (ec.terminated_on is null or ec.terminated_on>=m.competence_month)) select tenant_id,company_id,cost_center_id,competence_month,sum(base_salary*coalesce(allocation_percent,100)/100)::numeric(18,2) projected_salary from active_terms group by tenant_id,company_id,cost_center_id,competence_month;
create view public.budget_engineering_projection with(security_invoker=true) as select tenant_id,company_id,work_id,competence,sum(projected_amount)::numeric(18,2) projected_revenue from public.engineering_revenue_projections where status='active' group by tenant_id,company_id,work_id,competence;
create view public.budget_integrated_overview with(security_invoker=true) as with salary as(select tenant_id,company_id,cost_center_id,competence_month,sum(projected_salary)::numeric(18,2) salary_projection from public.budget_salary_projection group by tenant_id,company_id,cost_center_id,competence_month), manual as(select tenant_id,company_id,cost_center_id,competence_month,sum(planned_amount)::numeric(18,2) other_planned from public.budget_plans where source_kind<>'salary' group by tenant_id,company_id,cost_center_id,competence_month), actual as(select tenant_id,company_id,cost_center_id,competence_month,sum(actual_expense)::numeric(18,2) actual_expense,sum(actual_income)::numeric(18,2) actual_income from public.budget_monthly_control group by tenant_id,company_id,cost_center_id,competence_month), keys as(select tenant_id,company_id,cost_center_id,competence_month from salary union select tenant_id,company_id,cost_center_id,competence_month from manual union select tenant_id,company_id,cost_center_id,competence_month from actual) select k.tenant_id,k.company_id,k.cost_center_id,k.competence_month,coalesce(s.salary_projection,0)::numeric(18,2) salary_projection,coalesce(m.other_planned,0)::numeric(18,2) other_planned,(coalesce(s.salary_projection,0)+coalesce(m.other_planned,0))::numeric(18,2) total_planned_expense,coalesce(a.actual_expense,0)::numeric(18,2) actual_expense,coalesce(a.actual_income,0)::numeric(18,2) actual_income,(coalesce(s.salary_projection,0)+coalesce(m.other_planned,0)-coalesce(a.actual_expense,0))::numeric(18,2) planned_remaining from keys k left join salary s on s.tenant_id=k.tenant_id and s.company_id=k.company_id and s.cost_center_id is not distinct from k.cost_center_id and s.competence_month=k.competence_month left join manual m on m.tenant_id=k.tenant_id and m.company_id=k.company_id and m.cost_center_id is not distinct from k.cost_center_id and m.competence_month=k.competence_month left join actual a on a.tenant_id=k.tenant_id and a.company_id=k.company_id and a.cost_center_id is not distinct from k.cost_center_id and a.competence_month=k.competence_month;
commit;
